record.field:
Remote = self.remote_id
Sensor = env['mdm.measurement.device.sensor']
Reading = env['mdm.measurement.device.sensor.reading']
today_str = fields.Date.today()
condition = [
    ('remotecontrol_params', '!=', False),
    ('device_id.remotecontrol_id', '=', Remote.id)
]
if selected_device_ids:
    condition.append(('device_id', 'in', selected_device_ids))
sensors = Sensor.search(condition)
last_readings_map = {}
if sensors:
    readings = Reading.search(
        [('sensor_id', 'in', sensors.ids), ('active', '=', True)],
        order='sensor_id ASC, measurement_time DESC'
    )
    for r in readings:
        sid = r.sensor_id.id
        if sid not in last_readings_map:
            last_readings_map[sid] = r.measurement_time
plan = []
for sensor in sensors:
    device = sensor.device_id
    try:
        sensor_cfg = json.loads(sensor.remotecontrol_params or '{}') or {}
    except Exception:
        sensor_cfg = {}
    try:
        device_cfg = json.loads(device.remotecontrol_params or '{}') or {}
    except Exception:
        device_cfg = {}
    route = sensor_cfg.get('route')
    sensor_id_param = device_cfg.get('device_id')
    if not (route and sensor_id_param):
        continue
    last_reading_time = last_readings_map.get(sensor.id)
    start_dev = device_cfg.get('start_date')
    start_sensor = sensor_cfg.get('start_date')
    if last_reading_time:
        try:
            last_dt = fields.Datetime.from_string(last_reading_time)
            initial_date = fields.Date.to_string(last_dt)
        except Exception:
            initial_date = str(last_reading_time)[:10]
    elif start_dev:
        initial_date = start_dev[:10]
    elif start_sensor:
        initial_date = start_sensor[:10]
    else:
        initial_date = '%s-01-01' % today_str[:4]
    if isinstance(initial_date, unicode):
        initial_date = initial_date.encode('utf-8')
    plan.append({
        'sensor_id': sensor.id,
        'sensor_id_param': sensor_id_param,
        'route': route,
        'device_id': device.id,
        'initial_date': initial_date
    })
bag['sensors_plan'] = plan

location_variables_plan = []
location_condition = [
    ('remotecontrol_params', '!=', False),
    ('device_id.remotecontrol_id', '=', Remote.id)
]
if selected_device_ids:
    location_condition.append(('device_id', 'in', selected_device_ids))
location_sensors = Sensor.search(location_condition)

for sensor in location_sensors:
    device = sensor.device_id
    try:
        sensor_cfg = json.loads(sensor.remotecontrol_params or '{}') or {}
    except Exception:
        sensor_cfg = {}
    try:
        device_cfg = json.loads(device.remotecontrol_params or '{}') or {}
    except Exception:
        device_cfg = {}

    variable_id = sensor_cfg.get('variable_id')
    if not variable_id:
        continue

    last_reading_time = last_readings_map.get(sensor.id)
    start_dev = device_cfg.get('start_date')
    start_sensor = sensor_cfg.get('start_date')

    if last_reading_time:
        try:
            last_dt = fields.Datetime.from_string(last_reading_time)
            initial_date = fields.Date.to_string(last_dt)
        except Exception:
            initial_date = str(last_reading_time)[:10]
    elif start_sensor:
        initial_date = start_sensor[:10]
    elif start_dev:
        initial_date = start_dev[:10]
    else:
        initial_date = '%s-01-01' % today_str[:4]

    if isinstance(initial_date, unicode):
        initial_date = initial_date.encode('utf-8')

    location_variables_plan.append({
        'sensor_id': sensor.id,
        'variable_id': variable_id,
        'device_id': device.id,
        'initial_date': initial_date
    })

bag['location_variables_plan'] = location_variables_plan

import time
import pytz
from datetime import datetime, timedelta

Remote = self.remote_id
SensorModel = env['mdm.measurement.device.sensor']
Reading = env['mdm.measurement.device.sensor.reading']
today = datetime.now()
plan = bag.get('sensors_plan') or []
api_url = 'https://smart2.inelcom.com:28081/isrlrestws/resources/hidrantes'
total_upserts = 0
total_errors = 0
items = []


def get_token():
    cfg = {}
    try:
        cfg = json.loads(Remote.connection_params or '{}')
    except Exception:
        cfg = {}
    username = (cfg.get('username') or '').strip()
    password = (cfg.get('password') or '').strip()
    if not username or not password:
        msg = "Missing inelcom credentials: set username/password"
        raise Exception(msg)
    url = 'https://smart2.inelcom.com:28081/restws/webresources/sesiones'
    resp = request_retry('POST', url, json={
        'usuario': username,
        'clave': password
    })
    if resp.status_code >= 400:
        raise Exception("Login failed: %s %s" % (resp.status_code, resp.text))
    id_session = resp.text.strip()
    if not id_session:
        raise Exception("Login OK but empty token response")
    return id_session


for idx, sensor_plan in enumerate(plan, 1):
    sensor_id = sensor_plan['sensor_id']
    sensor_id_param = sensor_plan['sensor_id_param']
    device_id = sensor_plan['device_id']
    route = sensor_plan['route']
    initial_date = sensor_plan['initial_date']
    dt_initial = datetime.strptime(initial_date, '%Y-%m-%d')
    days = (today.date() - dt_initial.date()).days + 1
    if days < 1:
        days = 1
    date_ddmmyy = dt_initial.strftime('%d/%m/%y')
    try:
        id_session = get_token()
    except Exception as e:
        items.append({
            'sensor_id': sensor_id,
            'error': 'Token error: %s' % str(e)
        })
        total_errors += 1
        continue
    url = "%s/%s?sesion=%s&contador=%s&fecha=%s&dias=%s" % (
        api_url, route, id_session, sensor_id_param, date_ddmmyy, days
    )
    try:
        resp = request_retry('GET', url, timeout=timeout)
        code = resp.status_code
        full_url = getattr(resp, 'url', url)
        if code < 400:
            payload = resp.json() or {}
            upserts = 0
            errs = 0
            readings_summary = []
            all_readings = []
            lista = payload.get('lista', [])
            for entry in lista:
                try:
                    date_str = entry.get('fecha')
                    time_str = entry.get('hora')
                    value = entry.get('valor')
                    try:
                        dt = datetime.strptime(date_str, '%d/%m/%y')
                        dt = dt.replace(
                            hour=int(time_str[:2]),
                            minute=int(time_str[3:]),
                            second=0
                        )
                        date_time_read = pytz.timezone('Europe/Madrid').localize(dt)
                        date_time_read = date_time_read.astimezone(pytz.timezone('UTC'))
                        ts_str = date_time_read.strftime('%Y-%m-%d %H:%M:%S')
                    except Exception:
                        ts_str = initial_date + ' ' + time_str + ':00'
                    valf = float(value)
                    all_readings.append({'ts': ts_str, 'value': valf})
                    upserts += 1
                    if len(readings_summary) < 5:
                        readings_summary.append({'ts': ts_str, 'value': valf})
                except Exception as e:
                    errs += 1
                    if len(readings_summary) < 5:
                        readings_summary.append({
                            'error': str(e),
                            'raw': entry
                        })
            total_upserts += upserts
            total_errors += errs
            items.append({
                'sensor_id': sensor_id,
                'sensor_id_param': sensor_id_param,
                'device_id': device_id,
                'status': 200,
                'url': full_url,
                'points_found': len(lista),
                'upserts': upserts,
                'errors': errs,
                'readings': all_readings,
                'readings_summary': readings_summary
            })
        else:
            items.append({
                'sensor_id': sensor_id,
                'sensor_id_param': sensor_id_param,
                'device_id': device_id,
                'status': code,
                'error': (resp.text or '')[:400],
                'url': full_url
            })
    except Exception as e:
        items.append({
            'sensor_id': sensor_id,
            'sensor_id_param': sensor_id_param,
            'device_id': device_id,
            'status': -1,
            'error': str(e)
        })
    time.sleep(1)

audit = {
    'executed_at': fields.Datetime.now(),
    'total_upserts': total_upserts,
    'total_errors': total_errors,
    'items': items
}
audit_json = json.dumps(audit, ensure_ascii=False, indent=2).encode('utf-8')
b64 = base64.b64encode(audit_json)
now_str = fields.Datetime.now().replace(':', '').replace('-', '')
fname = 'inelcom_readings_%s.json' % now_str.replace(' ', '_')
att = env['ir.attachment'].create({
    'name': fname,
    'datas_fname': fname,
    'datas': b64,
    'mimetype': 'application/json',
    'res_model': 'remotecontrol',
    'res_id': Remote.id
})
Remote.message_post(
    body=u"[Inelcom] upserts=%s errors=%s" % (total_upserts, total_errors),
    attachment_ids=[att.id]
)
bag['raw_readings'] = []
bag['fetch_errors'] = total_errors
bag['audit_attachment_id'] = att.id
bag['total_sensors_planned'] = len(plan)
bag['sensors_processed'] = len(items)
bag['audit_filename'] = fname
success_items = [i for i in items if i.get('status') == 200]
success_rate = 0
if items:
    success_rate = float(len(success_items)) / len(items) * 100
bag['fetch_summary'] = {
    'executed_at': fields.Datetime.now(),
    'total_readings_fetched': total_upserts,
    'total_errors': total_errors,
    'sensors_in_plan': len(plan),
    'sensors_processed': len(items),
    'success_rate': '%.1f%%' % success_rate
}
for item in items:
    if item.get('status') == 200 and 'readings' in item:
        for reading in item['readings']:
            if 'ts' in reading and 'value' in reading:
                bag['raw_readings'].append({
                    'sensor_id': item['sensor_id'],
                    'device_id': item['device_id'],
                    'measurement_time': reading['ts'],
                    'value': reading['value']
                })
if len(items) <= 10:
    bag['detailed_results'] = items
else:
    truncated = {'truncated': '... %d more items ...' % (len(items) - 5)}
    bag['detailed_results'] = items[:5] + [truncated] + items[-5:]
bag['sensors_with_errors'] = [
    {'sensor_id': i.get('sensor_id'), 'error': i.get('error')}
    for i in items if i.get('error')
]

import time
import pytz
from datetime import datetime, timedelta

Remote = self.remote_id
SensorModel = env['mdm.measurement.device.sensor']
Reading = env['mdm.measurement.device.sensor.reading']
today = datetime.now()
plan = bag.get('location_variables_plan') or []
api_url = 'https://smart2.inelcom.com:28081/restws/webresources/emplazamientos/variables/historico'
total_upserts = 0
total_errors = 0
items = []

def get_token():
    cfg = {}
    try:
        cfg = json.loads(Remote.connection_params or '{}')
    except Exception:
        cfg = {}
    username = (cfg.get('username') or '').strip()
    password = (cfg.get('password') or '').strip()
    if not username or not password:
        msg = "Missing inelcom credentials: set username/password"
        raise Exception(msg)
    url = 'https://smart2.inelcom.com:28081/restws/webresources/sesiones'
    resp = request_retry('POST', url, json={
        'usuario': username,
        'clave': password
    })
    if resp.status_code >= 400:
        raise Exception("Login failed: %s %s" % (resp.status_code, resp.text))
    id_session = resp.text.strip()
    if not id_session:
        raise Exception("Login OK but empty token response")
    return id_session

for idx, variable_plan in enumerate(plan, 1):
    sensor_id = variable_plan['sensor_id']
    variable_id = variable_plan['variable_id']
    device_id = variable_plan['device_id']
    initial_date = variable_plan['initial_date']

    dt_initial = datetime.strptime(initial_date, '%Y-%m-%d')
    days = (today.date() - dt_initial.date()).days + 1
    if days < 1:
        days = 1
    date_ddmmyy = dt_initial.strftime('%d/%m/%y')

    try:
        id_session = get_token()
    except Exception as e:
        items.append({
            'sensor_id': sensor_id,
            'error': 'Token error: %s' % str(e)
        })
        total_errors += 1
        continue

    url = "%s?sesion=%s&variable=%s&fecha=%s&dias=%s" % (
        api_url, id_session, variable_id, date_ddmmyy, days
    )

    try:
        resp = request_retry('GET', url, timeout=timeout)
        code = resp.status_code
        full_url = getattr(resp, 'url', url)
        if code < 400:
            payload = resp.json() or {}
            upserts = 0
            errs = 0
            readings_summary = []
            all_readings = []
            readings_list = payload if isinstance(payload, list) else []
            for entry in readings_list:
                try:
                    date_str = entry.get('fecha')
                    time_str = entry.get('hora')
                    value = entry.get('valor')
                    try:
                        dt = datetime.strptime(date_str, '%d/%m/%y')
                        dt = dt.replace(
                            hour=int(time_str[:2]),
                            minute=int(time_str[3:]),
                            second=0
                        )
                        date_time_read = pytz.timezone('Europe/Madrid').localize(dt)
                        date_time_read = date_time_read.astimezone(pytz.timezone('UTC'))
                        ts_str = date_time_read.strftime('%Y-%m-%d %H:%M:%S')
                    except Exception:
                        ts_str = initial_date + ' ' + time_str + ':00'

                    valf = float(value)
                    all_readings.append({'ts': ts_str, 'value': valf})
                    upserts += 1

                    if len(readings_summary) < 5:
                        readings_summary.append({'ts': ts_str, 'value': valf})
                except Exception as e:
                    errs += 1
                    if len(readings_summary) < 5:
                        readings_summary.append({
                            'error': str(e),
                            'raw': entry
                        })

            total_upserts += upserts
            total_errors += errs

            items.append({
                'sensor_id': sensor_id,
                'variable_id': variable_id,
                'device_id': device_id,
                'status': 200,
                'url': full_url,
                'points_found': len(readings_list),
                'upserts': upserts,
                'errors': errs,
                'readings': all_readings,
                'readings_summary': readings_summary
            })
        else:
            items.append({
                'sensor_id': sensor_id,
                'variable_id': variable_id,
                'device_id': device_id,
                'status': code,
                'error': (resp.text or '')[:400],
                'url': full_url
            })
    except Exception as e:
        items.append({
            'sensor_id': sensor_id,
            'variable_id': variable_id,
            'device_id': device_id,
            'status': -1,
            'error': str(e)
        })

    time.sleep(1)

existing_raw = bag.get('raw_readings') or []
for item in items:
    if item.get('status') == 200 and 'readings' in item:
        for reading in item['readings']:
            if 'ts' in reading and 'value' in reading:
                existing_raw.append({
                    'sensor_id': item['sensor_id'],
                    'device_id': item['device_id'],
                    'measurement_time': reading['ts'],
                    'value': reading['value']
                })

bag['raw_readings'] = existing_raw

Remote = self.remote_id
raw_readings = bag.get('raw_readings') or []
total_upserts = 0
total_errors = 0
upsert_results = []

for reading_data in raw_readings:
    try:
        Remote.upsert(
            'mdm.measurement.device.sensor.reading',
            {
                'sensor_id': reading_data['sensor_id'],
                'measurement_time': reading_data['measurement_time']
            },
            {
                'value': reading_data['value'],
                'device_id': reading_data['device_id']
            }
        )
        total_upserts += 1
        if len(upsert_results) < 10:
            upsert_results.append({
                'sensor_id': reading_data['sensor_id'],
                'measurement_time': reading_data['measurement_time'],
                'value': reading_data['value'],
                'status': 'success'
            })
    except Exception as e:
        total_errors += 1
        if len(upsert_results) < 10:
            upsert_results.append({
                'sensor_id': reading_data['sensor_id'],
                'measurement_time': reading_data['measurement_time'],
                'value': reading_data['value'],
                'status': 'error',
                'error': str(e)
            })

bag['upserts'] = total_upserts
bag['upsert_errors'] = total_errors
bag['upsert_results'] = upsert_results
success_rate = 0
if raw_readings:
    success_rate = float(total_upserts) / len(raw_readings) * 100
bag['upsert_summary'] = {
    'executed_at': fields.Datetime.now(),
    'total_readings_processed': len(raw_readings),
    'successful_upserts': total_upserts,
    'failed_upserts': total_errors,
    'success_rate': '%.1f%%' % success_rate
}
msg = "[Inelcom] Upserts: %s successful, %s errors from %s readings"
Remote.message_post(
    body=u"" + msg % (total_upserts, total_errors, len(raw_readings))
)
